from mk import *
R=[]
R.append((9967440,"Saus Enchilada Buatan Sendiri","Saus enchilada buatan sendiri siap dalam 15 menit, jadi Anda bisa mengucapkan selamat tinggal pada yang kalengan selamanya! Pedas, lezat, MUDAH!","2 Cangkir","4 sdm",
["1-3 jalapeno, dicincang sangat halus","2 cangkir kaldu sayuran rendah natrium","4 sendok makan pasta tomat","1 sendok teh bawang putih bubuk","1 sendok teh cabai bubuk","1 sendok teh jintan","½ sendok teh garam laut","1 sendok makan tepung maizena untuk mengentalkan, OPSIONAL"],
["Masukkan jalapeno bersama satu atau dua sendok makan kaldu ke dalam panci kecil dan tumis selama 2 menit.","Masukkan semua bahan yang tersisa, aduk rata dan didihkan. Lalu kecilkan api menjadi sedang-kecil dan didihkan perlahan selama 8 menit hingga sedikit menyusut.","Gunakan dalam hidangan Meksiko favorit Anda."],
["Gunakan 1 hingga 3 jalapeno tergantung tingkat kepedasan yang Anda sukai. Jika Anda menginginkan saus yang lebih ringan, gunakan 1 jalapeno dan buang bijinya. Untuk sedang, 1-2 dengan bijinya dibiarkan. Untuk pedas, gunakan 3 jalapeno beserta bijinya. Simpan sisa dalam wadah tertutup atau toples di lemari es hingga 5 hari. Atau Anda dapat membekukannya hingga 1 bulan. Anda dapat memblender saus setelah mendidih perlahan, jika diinginkan. Tetapi jika Anda mencincang jalapeno sangat halus, tidak perlu. Tepung maizena opsional berfungsi dengan baik jika Anda menggunakan saus langsung apa adanya. Jika Anda menambahkan saus ke Veggie Enchilada Casserole saya, lewati tepung maizena. Informasi nutrisi adalah untuk ⅛ saus, sekitar 4 sendok makan atau ¼ cangkir."],[]))
J="Untuk Nangka Muda";TP="Topping & Dip Opsional"
R.append((9968027,"Nachos Nangka Suwir dengan Saus BBQ Buatan Sendiri","Nachos vegan yang lezat diberi topping nangka yang dilumuri saus BBQ buatan sendiri yang lezat. Siap dalam 20 menit!","4 Porsi","1 porsi",
[(J,"1 kantong 220 gram keripik tortilla multigrain atau pilihan Anda"),(J,"1 kaleng 20 oz nangka muda hijau, ditiriskan & dibilas (jenis dalam air atau air garam, bukan sirup)"),(J,"3 sendok makan pasta tomat"),(J,"¼ cangkir cuka sari apel"),(J,"1 sendok makan sirup maple"),(J,"1 sendok teh mustard kuning"),(J,"2 sendok makan tamari atau kecap asin (atau ½ sendok teh garam)"),(J,"¼ cangkir air"),(J,"2 sendok teh bawang bombai bubuk"),(J,"2 sendok teh bawang putih bubuk"),(J,"½ sendok teh paprika asap"),(J,"¼ sendok teh cabai cayenne, opsional"),(TP,"kacang hitam"),(TP,"jagung"),(TP,"jalapeno"),(TP,"zaitun"),(TP,"daun ketumbar segar"),(TP,"guacamole"),(TP,"krim mete"),(TP,"salsa"),(TP,"saus keju bebas kacang"),(TP,"dip pedas \"Jalapeno Popper\"")],
["Campurkan semua bahan saus bbq dalam mangkuk sedang dan aduk rata. Sisihkan.","Suwir potongan nangka menggunakan tangan atau dua garpu. Nangka akan mudah disuwir, lalu letakkan dalam wajan besar. Kemudian tuang saus di atasnya dan aduk rata.","Dengan api sedang, masak nangka dalam saus, awalnya akan sedikit berkuah tetapi akan cepat menyerap saus saat dimasak. Ini akan memakan waktu sekitar 5-8 menit.","Sementara itu, susun keripik Anda dalam piring saji, dan setelah siap, beri topping nangka dan topping pilihan Anda. Sajikan nachos nangka Anda dengan guacamole, krim mete, dan/atau salsa."],
["Pastikan membeli nangka yang dikalengkan dalam air atau air garam, bukan sirup. Jenis yang bersirup sangat manis dan Anda ingin nangka menyerap rasa saus BBQ, bukan didominasi rasa sirup. Jika Anda kekurangan waktu, atau tidak ingin membuat saus BBQ sendiri, Anda dapat menggantinya dengan saus yang dibeli di toko. Gunakan sekitar ¾ cangkir saus siap pakai sebagai pengganti versi buatan sendiri. Jika Anda lebih suka tepi nangka yang renyah, pindahkan setelah matang ke loyang dalam satu lapisan dan panggang pada 375 derajat selama 15-20 menit sebelum ditambahkan ke nachos Anda. Untuk keripik bebas minyak, berikut resep dari Sweet Simple Vegan untuk membuat keripik tortilla sehat sendiri. Ingat, nangka adalah bintang hidangan ini, jadi tambahkan lapisan yang banyak di atas keripik Anda sebelum menaburkan topping tambahan. Jika ada sisa, simpan dalam wadah tertutup di lemari es hingga 5 hari. Gunakan sisa Anda untuk membuat sandwich gaya \"pulled pork\" vegan dengan topping coleslaw vegan lembut saya."],[]))
R.append((9969020,"Hummus Paprika Merah Panggang Bebas Minyak","Hummus paprika merah panggang yang beraroma asap dan lezat, sangat halus tanpa minyak dan tanpa tahini.","6 Porsi (menghasilkan sekitar 2 cangkir)","1 porsi",
["1 toples 12 ounce paprika merah panggang, sekitar 2 paprika","1.5 cangkir buncis (chickpea) matang atau kalengan (sekitar 1 kaleng 15 oz)","2 sendok makan air lemon","1-2 siung bawang putih, dikupas","½ sendok teh garam laut atau secukupnya","½ sendok teh paprika asap","¼ sendok teh cabai cayenne","2-4 sendok makan air untuk mengencerkan"],
["Masukkan semua bahan ke dalam blender Anda, mulai dengan 2 sendok makan air. Blender hingga halus.","Cicipi dan sesuaikan garam jika perlu dan tambahkan 2 sendok makan air lagi jika lebih suka kekentalan yang lebih encer.","Sajikan dengan sayuran, pita, keripik tortilla, atau apa pun yang Anda inginkan."],
["Gunakan paprika merah panggang yang dikemas dalam air (bukan minyak) agar kandungan lemak tetap rendah. Atau panggang paprika Anda sendiri jika diinginkan. Jika memanggang paprika sendiri, buang sebagian besar kulit yang gosong/hitam, tetapi jangan khawatir menghilangkan setiap potongan kecil karena potongan itu akan menambah kedalaman rasa yang lebih kuat. Simpan sisa dalam wadah tertutup di lemari es hingga 5 hari. Atau bekukan dalam wadah kedap udara hingga 3 bulan."],[]))
RC="Untuk keju ricotta vegan";SA="Untuk saus"
R.append((9969110,"Gulungan Zukini Vegan","Zukini yang empuk, keju ricotta vegan, saus marinara, dan parmesan vegan menjadikan makanan penghibur sehat yang terbaik.","6 Porsi","1 porsi",
["2 pon zukini, sekitar 3 zukini sedang",(RC,"1.5 cangkir mete mentah"),(RC,"¼ cangkir nutritional yeast"),(RC,"2 sendok makan cuka sari apel"),(RC,"½ sendok teh bawang putih bubuk"),(RC,"½ sendok teh garam laut"),(RC,"½ cangkir air"),(SA,"1.5 cangkir saus tomat atau puree"),(SA,"2-3 sendok makan basil segar, dicincang halus"),(SA,"½ sendok teh oregano kering"),("Hiasan opsional","½ cangkir parmesan vegan")],
["Panaskan oven terlebih dahulu hingga 375 derajat F (190 derajat C). Lalu siapkan loyang besar dan alasi dengan tisu dapur atau lap dapur bersih.","Iris zukini memanjang setebal 1/8 inci. Susun irisan dalam satu lapisan di atas loyang Anda dan taburi garam secukupnya. Sisihkan dan diamkan selama 15 menit. (Garam akan melunakkan zukini, mengeluarkan kelebihan air dan membuatnya lentur untuk digulung.)","Sementara itu, siapkan keju Anda dengan memasukkan semua bahan ricotta vegan ke dalam food processor. Haluskan hingga lembut dan sisihkan.","Sekarang, campurkan bahan saus dalam mangkuk kecil dan sisihkan.","Sekarang, zukini Anda seharusnya sudah siap digulung. Tepuk irisan hingga kering untuk menghilangkan kelebihan air. Lalu oleskan 1 cangkir saus tomat yang sudah disiapkan di dasar loyang atau wajan besi cor 10 inci. (Atau wadah tahan oven lainnya.)","Masukkan sekitar satu sendok teh campuran ricotta ke satu irisan zukini, lalu mulai dari bawah, gulung. Letakkan di loyang Anda, berdiri tegak, di atas lapisan saus tomat. Ulangi dengan sisa irisan. Lalu beri topping sisa saus di atas gulungan zukini, dan taburi dengan parmesan vegan, jika digunakan.","Tutup dengan penutup, atau kertas roti, diikuti aluminium foil, dan panggang selama 20-25 menit, hingga zukini empuk, tetapi tidak terlalu matang. Keluarkan dari oven dan sajikan."],
["Jika Anda tidak punya blender berkecepatan tinggi, rendam mete Anda dalam air mendidih selama 30 menit, lalu tiriskan, sebelum diproses. Jangan lewatkan penggaraman zukini. Langkah ini yang membuat zukini Anda cukup lunak untuk digulung sambil mengeluarkan kelebihan air. Sisa makanan dapat disimpan di lemari es selama 2-3 hari atau dibekukan hingga 3 bulan."],[]))
R.append((9970596,"Kacang Refried Bebas Minyak","Resep super sederhana untuk kacang refried bebas minyak yang LEZAT yang dapat Anda buat hanya dalam 25 menit.","8 Porsi","1 porsi",
["4 sendok makan kaldu sayuran","½ cangkir bawang bombai putih, dipotong dadu","2-3 siung bawang putih, dicincang halus","1 sendok teh cabai bubuk","1 sendok teh paprika asap","½ sendok teh jintan","3 cangkir kacang pinto matang atau kalengan","¾ cangkir kaldu sayuran","2 sendok makan daun ketumbar segar","1-2 sendok makan air jeruk nipis"],
["Masukkan empat sendok makan kaldu ke dalam wajan besar bersama bawang bombai potong dadu. Tumis hingga lunak, sekitar 4-5 menit, tambahkan lebih banyak kaldu atau air, jika perlu agar tidak menempel.","Lalu tambahkan bawang putih dan bumbu-bumbu, aduk rata dan masak 30 detik lagi.","Selanjutnya, masukkan kacang pinto dan sisa 3/4 cangkir kaldu ke dalam wajan dan didihkan perlahan selama 5 menit, hingga cairan sebagian besar menyusut. Matikan api dan gunakan penumbuk kentang untuk menumbuk sebagian besar kacang.","Sekarang tambahkan ketumbar, dan air jeruk nipis, dan aduk rata. Cicipi garamnya dan tambahkan jika perlu. (Ini akan tergantung pada keasinan kaldu Anda.)","Gunakan dalam hidangan seperti burrito, taco, fajita, dan lainnya!"],
["Gunakan kaldu berkualitas baik, beraroma/asin untuk rasa terbaik. Saya menggunakan campuran bouillon buatan sendiri ini. Jika menggunakan kaldu rendah natrium, Anda mungkin perlu menambahkan sedikit garam pada hasil akhirnya. Cicipi dan sesuaikan sesuai kebutuhan. Untuk kacang refried yang lebih halus, tumbuk lebih lama atau gunakan food processor atau blender jika Anda tidak menginginkan tekstur sama sekali. Sisa kacang refried dapat disimpan dalam wadah kedap udara di lemari es selama 3-4 hari atau dibekukan dalam wadah yang aman untuk freezer hingga 6 bulan."],[]))
R.append((9973119,"Tater Tot Zukini Panggang","Tater tot zukini panggang adalah pilihan yang lebih sehat untuk makanan keluarga. Sangat penuh rasa dengan bagian luar renyah dan bagian tengah lembut dan empuk.","4 porsi (sekitar 24-30 tater)","1 porsi",
["1 pon kentang kuning (5-6 kentang kecil), dikupas","300 gram zukini, sekitar 1 sedang atau 2 kecil","1 sendok teh paprika","1 sendok teh bawang putih bubuk","½ sendok teh garam laut"],
["Letakkan kentang dalam panci sedang dan tutupi dengan air. Didihkan dan masak selama 8-10 menit, hingga garpu dapat menembus tepinya. Jangan terlalu matang atau akan terlalu lunak untuk diparut. Tiriskan dan bilas dengan air dingin segera, lalu tepuk hingga kering. Sisihkan.","Sementara itu, parut zukini Anda di atas tisu dapur atau lap dapur bersih. Lalu peras air sebanyak mungkin di atas bak cuci dapur Anda. Pindahkan zukini parut ke mangkuk adonan besar lalu parut kentang ke dalam mangkuk yang sama dan tambahkan bumbu. Aduk rata.","Panaskan oven terlebih dahulu hingga 425°F / 218°C dan alasi loyang besar dengan kertas roti.","Gunakan tangan Anda untuk membentuk campuran menjadi bentuk silinder, menggunakan sekitar 1 sendok makan campuran untuk masing-masing. Buat tater tot tetap kecil untuk tekstur yang lebih renyah. Letakkan masing-masing di loyang yang sudah disiapkan dan ulangi dengan sisa campuran. Anda akan mendapatkan 24-30 tater tot.","Panggang selama 20-25 menit, lalu balik dengan hati-hati dan panggang 10 menit lagi, hingga tingkat kerenyahan yang diinginkan tercapai."],
["Jangan memasak kentang terlalu lama atau akan terlalu lunak dan sulit diparut. Peras air sebanyak mungkin dari zukini parut sebelum dicampur dengan kentang. Anda tidak menginginkan terlalu banyak kelebihan air. Buat tater tot tetap kecil untuk tekstur yang lebih renyah. Karena tidak ada minyak dalam resep ini, berhati-hatilah saat membalik. Jika tater terasa sedikit menempel atau sulit dibalik, panggang beberapa menit lebih lama agar lebih padat dan coba lagi. Ini paling enak saat baru dibuat tetapi Anda dapat menyimpan sisa di lemari es selama 3-4 hari. Panaskan kembali di oven, air fryer, atau toaster oven untuk mengembalikan kerenyahannya."],[]))
DR="Bahan Dressing"
R.append((9975367,"Wrap Vegan Slaw Asia dengan Nasi Kembang Kol","Untuk wrap segar yang LUAR BIASA dengan rasa kacang yang lezat, tidak perlu mencari lagi selain wrap vegan slaw Asia yang bergizi ini. Sempurna untuk menjamu banyak orang.","8 Wrap","1 porsi",
["1 sendok teh minyak kelapa *lihat opsi bebas minyak di catatan di bawah","1 kepala kembang kol kecil atau setengah yang besar, menghasilkan 4 cangkir kembang kol cincang seperti nasi","½ sendok teh garam laut","4 cangkir campuran slaw, saya menggunakan campuran bit, brokoli & wortel (atau buat sendiri!)","¼ cangkir daun ketumbar segar, dicincang","8 tortilla wrap 10 inci, bebas gluten jika perlu",(DR,"2 sendok makan selai kacang halus"),(DR,"3 sendok makan tamari atau kecap asin"),(DR,"3 sendok makan cuka beras"),(DR,"2 sendok makan sirup maple"),(DR,"1 sendok makan air jeruk nipis, sekitar setengah jeruk nipis"),(DR,"½ sendok teh bawang putih bubuk"),(DR,"½ sendok teh sriracha, opsional")],
["Menggunakan food processor atau veggie bullet, cincang kembang kol Anda hingga seperti nasi. Jika menggunakan food processor, lakukan dalam porsi yang lebih kecil agar kembang kol tidak terlalu halus. Anda tidak menginginkannya menjadi puree.","Panaskan minyak kelapa dalam wajan besar dengan api sedang-besar dan tunggu hingga minyak panas. Lalu masukkan nasi kembang kol Anda dan taburi dengan garam. Masak, sesekali diaduk selama sekitar 10 menit, atau hingga keemasan muda. Sisihkan.","Sementara itu, masukkan semua bahan dressing Anda ke dalam mangkuk kecil dan kocok hingga tercampur. Sisihkan.","Letakkan slaw dan ketumbar dalam mangkuk besar lalu tuang dressing di atasnya dan aduk rata.","Bagi nasi kembang kol Anda dan slaw yang sudah diberi dressing ke dalam 8 wrap Anda. Anda akan menambahkan sekitar 2 sendok makan nasi kembang kol dan 3 sendok makan slaw ke setiap wrap. Lipat sisi-sisi tortilla wrap terlebih dahulu lalu gulung dari bawah agar tidak ada yang tumpah dari tepinya. Jangan mengisi terlalu penuh atau akan sulit digulung.","Opsional tetapi direkomendasikan: Gunakan panini press atau panggangan untuk memanggang wrap Anda sebentar, dengan sisi lipatan menghadap ke bawah, selama sekitar 2 menit. Ini akan membantu menahan wrap Anda dan memberi garis panggangan yang indah.","Sajikan wrap Anda dipotong dua atau utuh. Selamat menikmati!"],
["Jangan mengisi wrap vegan Anda terlalu penuh. Selain sulit dilipat, juga akan jauh lebih berantakan saat dimakan. Untuk menghemat waktu, Anda dapat membeli coleslaw siap pakai (pilih campuran sayuran favorit Anda). Anda juga dapat membeli nasi kembang kol siap pakai. Anda memerlukan 4 cangkir masing-masing. Jika Anda punya waktu, saya sangat merekomendasikan memanggang wrap vegan. Ini membantu menahan wrap, menutup tepinya agar menjadi kantong yang rapi. Untuk bebas minyak: Tumis nasi kembang kol Anda dalam air atau kaldu sebagai pengganti minyak kelapa."],[]))
R.append((9980070,"Hummus Selai Kacang","Hummus selai kacang ini kaya protein dan beraroma lezat ala Thailand. Cobalah dengan nampan sayuran & kerupuk Anda berikutnya.","2 Cangkir","1 sdm",
["1 kaleng 15 oz buncis (chickpea), ditiriskan & dibilas","¼ cangkir selai kacang halus","½ jeruk nipis yang baru diperas","3 sendok makan tamari atau kecap asin jika tidak menghindari gluten","1 sendok makan sirup maple","¼ sendok teh bawang putih bubuk","¼ sendok teh jahe bubuk","¼ sendok teh cabai cayenne"],
["Masukkan semua bahan ke dalam food processor dan proses hingga halus dan tercampur.","Opsional: Sajikan dengan taburan tambahan cabai cayenne atau paprika jika diinginkan."],[],[]))
R.append((9983478,"Overnight Oats Labu","Resep overnight oats labu yang lezat dan bergizi yang sempurna untuk pagi hari yang sibuk.","1 Porsi","1 porsi",
["1/2 cangkir puree labu (BUKAN isian pai labu)","1/2 cangkir oat gulung","2/3 cangkir susu nabati tanpa pemanis (saya suka kedelai, oat, atau almond)","2 sendok makan biji chia","2 sendok teh sirup maple","1 sendok teh bumbu pai labu","choco chip, belahan pecan, buah segar"],
["Masukkan semuanya ke dalam mangkuk kecil, dan aduk hingga tercampur.","Dinginkan di lemari es semalaman, atau minimal 4 jam. Lalu tambahkan topping favorit Anda dan nikmati."],[],[]))
